/**
 * App version + user-facing update notes. GENERATED by
 * scripts/bump-version.mjs — do not edit by hand (the shape of this file is
 * part of that script's contract; check-version.mjs pins APP_VERSION to the
 * six manifest copies).
 *
 * Each note carries all shipped UI languages (update-note i18n discipline,
 * AGENTS.md 2026-10-03): dates use the YYYY.MM.DD form, and the newest entry
 * must ship every language — version-notes.test.ts enforces both.
 */

export const APP_VERSION = '0.1.8-beta.28';

export const NOTE_LANGS = ['en', 'zh', 'zh-tw', 'cs', 'nl', 'fr', 'he', 'ja', 'ko', 'pl', 'pt-br', 'es', 'tr'] as const;
export type NoteLang = (typeof NOTE_LANGS)[number];

export interface VersionNote {
  version: string;
  date: string; // YYYY.MM.DD
  note: Partial<Record<NoteLang, string>> & { en: string };
}

/**
 * Note text for a UI language. Hong Kong reads the Taiwan wording, and any
 * missing language falls back to Simplified Chinese then English — a
 * freshly bumped note renders sensibly until its translations land.
 */
export function noteText(note: VersionNote['note'], lang: string): string {
  const byLang = note as Partial<Record<string, string>>;
  if (lang === 'zh-hk') lang = 'zh-tw';
  return byLang[lang] ?? note.zh ?? note.en;
}

